        // Delphi: procedure TUSBPanel.GetUSBBuffer
        protected internal void GetUSBBuffer()
        {
            uint pending = (uint)0;
            uint rcvd = (uint)0;
            char[] RcvdChar = new char[3];
            int iPortStatus = 0;
            if (fSendBufferImage != null)
            {
                fSendBufferImage.ImageIndex = 2;
            }
            if (!Rtl.ComponentState.Contains(Rtl.csDesigning))
            {
                if (fOpen)
                {
                    if (USBPanel.FT_GetQueueStatus != null)
                    {
                        iPortStatus = USBPanel.FT_EE_Read(fFT_Handle, fActualProgramData /* @ */);
                        switch (iPortStatus)
                        {
                            case USBPanel.FT_UNFORMATTED_EEPROM:
                                {
                                    if (fAutoProgram)
                                    {
                                        if (fOnBlankEEProm != null)
                                        {
                                            fOnBlankEEProm(this);
                                        }
                                        if (USBPanel.FT_EE_Program != null)
                                        {
                                            if (Program_Device())
                                            {
                                                iPortStatus = USBPanel.FT_EE_Program(fFT_Handle, fProgramProgramData /* @ */);
                                            }
                                        }
                                        if (fOnProgram != null)
                                        {
                                            fOnProgram(this);
                                        }
                                    }
                                }
                                break;
                            case USBPanel.FT_INVALID_HANDLE:
                                {
                                    fRxStretch = 0;
                                    return;
                                }
                                break;
                        }
                        if (FT_Error_Check("Reading from USB Port", iPortStatus))
                        {
                            if (!FT_Error_Check("Reading from USB Port", USBPanel.FT_GetQueueStatus(fFT_Handle, pending /* @ */)))
                            {
                                pending = 0;
                            }
                            if (pending > 0)
                            {
                                if (fRcvBufferImage != null)
                                {
                                    fRcvBufferImage.ImageIndex = 1;
                                }
                                fRxStretch = 3;
                            }
                            else
                            {
                                if (fRxStretch > 0)
                                {
                                    fRxStretch--;
                                }
                                else
                                {
                                    if (fRcvBufferImage != null)
                                    {
                                        fRcvBufferImage.ImageIndex = 0;
                                    }
                                }
                            }
                            while (pending > 0)
                            {
                                if (fRcvBufferImage != null)
                                {
                                    fRcvBufferImage.ImageIndex = 1;
                                }
                                fTimeoutCountDown = fTimeout;
                                if (FT_Error_Check("Reading from USB Port", USBPanel.FT_Read(fFT_Handle, RcvdChar /* @ */, 1, rcvd /* @ */)))
                                {
                                    if (fRcvUSBBufferCount < this.fReadBufferSize)
                                    {
                                        fReadBuffer[fRcvUSBBufferCount] = RcvdChar[0];
                                        fRcvUSBBufferCount++;
                                    }
                                    if (fOnChar != null)
                                    {
                                        fOnChar(this, RcvdChar[0]);
                                    }
                                    if (!FT_Error_Check("Reading from USB Port", USBPanel.FT_GetQueueStatus(fFT_Handle, pending /* @ */)))
                                    {
                                        pending = 0;
                                    }
                                }
                                else
                                {
                                    pending = 0;
                                }
                            }
                        }
                        else
                        {
                        }
                    }
                }
            }
        }

