        // Delphi: procedure TUSBPanel.fTimerAction(Sender: TObject)
        protected internal virtual void fTimerAction(object Sender)
        {
            int rPtr = 0;
            DetectedDeviceCount = (int)GetFTDeviceCount();
            if (fOpen)
            {
                if (fDelayCount > 0)
                {
                    fDelayCount--;
                }
                else
                {
                    if (fWriteBufferPending > 0)
                    {
                        FT_Error_Check("writing to USB port", USBPanel.FT_Write(fFT_Handle, fWriteBuffer, fWriteBufferPending, rPtr /* @ */));
                        fWriteBufferPending = 0;
                    }
                    try
                    {
                        GetUSBBuffer();
                    }
                    catch (Exception)
                    {
                        return;
                    }
                    if (fTxStretch == 0)
                    {
                        if (fSendBufferImage != null)
                        {
                            fSendBufferImage.ImageIndex = 0;
                        }
                    }
                    else
                    {
                        fTxStretch--;
                    }
                }
            }
            if (fTimeoutCountDown > 0)
            {
                fTimeoutCountDown--;
                if (fTimeoutCountDown == 0)
                {
                    if (fOnTimeOut != null)
                    {
                        fOnTimeOut(this);
                    }
                    if (fRcvBufferImage != null)
                    {
                        fRcvBufferImage.ImageIndex = 3;
                    }
                }
            }
        }

