        // Delphi: procedure TUSBPanel.Open_USB_ByID
        public void Open_USB_ByID()
        {
            int i = 0;
            int iPortStatus = 0;
            if (USBPanel.FT_Open != null)
            {
                DetectedDeviceCount = (int)GetFTDeviceCount();
                {
                    int __end1 = DetectedDeviceCount - 1; // Delphi evaluates the loop bound once
                    for (i = 0; i <= __end1; i++)
                    {
                        try
                        {
                            iPortStatus = USBPanel.FT_Open(i, fFT_Handle /* @ */);
                            if (iPortStatus == USBPanel.FT_UNFORMATTED_EEPROM || iPortStatus == USBPanel.FT_INVALID_HANDLE)
                            {
                                if (fAutoProgram)
                                {
                                    if (fOnBlankEEProm != null)
                                    {
                                        fOnBlankEEProm(this);
                                    }
                                    if (USBPanel.FT_EE_Program != null)
                                    {
                                        iPortStatus = USBPanel.FT_EE_Program(fFT_Handle, fProgramProgramData /* @ */);
                                    }
                                    if (fOnProgram != null)
                                    {
                                        fOnProgram(this);
                                    }
                                }
                            }
                            if (FT_Error_Check("Opening USB", iPortStatus))
                            {
                                if (Read_Device())
                                {
                                    if (fProgramProgramData.Vendor_ID == fActualProgramData.Vendor_ID && fProgramProgramData.Product_ID == fActualProgramData.Product_ID)
                                    {
                                        if (fOpenMethod == TUSB_OpenMethod.omByID || AnsiStrings.AnsiStrComp(fProgramSerialNo, fActualSerialNo) == 0)
                                        {
                                            fOpen = true;
                                            fDeviceNo = (uint)i;
                                            SetCurrentBaudRate();
                                            SetDataCharacteristics();
                                            fShowOpenImage();
                                            return;
                                        }
                                    }
                                }
                            }
                            if (USBPanel.FT_Close != null)
                            {
                                USBPanel.FT_Close(fFT_Handle);
                            }
                        }
                        catch (Exception)
                        {
                        }
                    }
                }
            }
            fOpen = false;
            fShowOpenImage();
            switch (ErrorStyle)
            {
                case tErrorStyle.esThrowErrors:
                    {
                        throw new Exception("Error opening by ID");
                    }
                    break;
                case tErrorStyle.esPopUpErrors:
                    {
                        Rtl.MessageDlg("Error opening by ID", Rtl.mtError, new HashSet<TMsgDlgBtn> { Rtl.mbOK }, 0);
                    }
                    break;
            }
        }

        // Delphi: procedure TUSBPanel.Open_USB_ByDevice
        public void Open_USB_ByDevice()
        {
            if (USBPanel.FT_Open != null)
            {
                try
                {
                    if (FT_Error_Check("Opening USB", USBPanel.FT_Open((int)fDeviceNo, fFT_Handle /* @ */)))
                    {
                        fOpen = true;
                        SetCurrentBaudRate();
                        SetDataCharacteristics();
                    }
                    fShowOpenImage();
                }
                catch (Exception)
                {
                    fOpen = false;
                    fShowOpenImage();
                    throw;
                }
            }
        }

    }

