        // Delphi: procedure TUSBGrid.fTimerAction(Sender: TObject)
        protected internal void fTimerAction(object Sender)
        {
            int iNewDeviceCount = 0;
            try
            {
                iNewDeviceCount = (int)GetFTDeviceCount();
                if (iNewDeviceCount != fDeviceCount)
                {
                    fDeviceCount = iNewDeviceCount;
                    fFillGrid();
                }
            }
            catch (Exception)
            {
            }
        }

        // Delphi: procedure TUSBGrid.fFillGrid
        protected internal void fFillGrid()
        {
            int i = 0;
            int j = 0;
            int iRowCount = 0;
            uint iUSBHandle = (uint)0;
            int iPortStatus = 0;
            iRowCount = (int)GetFTDeviceCount();
            if (iRowCount == 0 || !fActiveMonitor)
            {
                RowCount = 2;
                {
                    int __end1 = ColCount - 1; // Delphi evaluates the loop bound once
                    for (i = 0; i <= __end1; i++)
                    {
                        Cells[i, 1] = "";
                    }
                }
            }
            else
            {
                RowCount = iRowCount + 1;
                for (i = 0; i <= iRowCount - 1; i++)
                {
                    Cells[USBPanel.cIndex, i + 1] = Rtl.IntToStr(i);
                    {
                        int __end2 = ColCount - 1; // Delphi evaluates the loop bound once
                        for (j = 1; j <= __end2; j++)
                        {
                            Cells[j, i + 1] = "";
                        }
                    }
                    if (USBPanel.FT_Open != null)
                    {
                        if (FT_Error_Check("Opening device " + Rtl.IntToStr(i), USBPanel.FT_Open(i, iUSBHandle /* @ */)))
                        {
                            if (USBPanel.FT_EE_Read != null)
                            {
                                fActualProgramData = fDefaultProgramData;
                                fActualProgramData.Manufacturer = Rtl.StrPas(fActualManufacturer /* @ */);
                                fActualProgramData.ManufacturerID = Rtl.StrPas(fActualManufacturerID /* @ */);
                                fActualProgramData.Description = Rtl.StrPas(fActualDescription /* @ */);
                                fActualProgramData.SerialNo = Rtl.StrPas(fActualSerialNo /* @ */);
                                AnsiStrings.StrCopy(fActualManufacturer, fDefaultManufacturer);
                                AnsiStrings.StrCopy(fActualManufacturerID, fDefaultManufacturerID);
                                AnsiStrings.StrCopy(fActualDescription, fDefaultDescription);
                                AnsiStrings.StrCopy(fActualSerialNo, fDefaultSerialNo);
                                iPortStatus = USBPanel.FT_EE_Read(iUSBHandle, fActualProgramData /* @ */);
                                switch (iPortStatus)
                                {
                                    case USBPanel.FT_UNFORMATTED_EEPROM:
                                        {
                                            if (USBPanel.FT_EE_Program != null)
                                            {
                                                iPortStatus = USBPanel.FT_EE_Program(iUSBHandle, fActualProgramData /* @ */);
                                            }
                                        }
                                        break;
                                }
                                switch (iPortStatus)
                                {
                                    case USBPanel.FT_OK:
                                        {
                                            Cells[USBPanel.cVendorID, i + 1] = Rtl.IntToHex(fActualProgramData.Vendor_ID, 4);
                                            Cells[USBPanel.cProductID, i + 1] = Rtl.IntToHex(fActualProgramData.Product_ID, 4);
                                            Cells[USBPanel.cManufacturer, i + 1] = fActualProgramData.Manufacturer;
                                            Cells[USBPanel.cManufacturerID, i + 1] = fActualProgramData.ManufacturerID;
                                            Cells[USBPanel.cDescription, i + 1] = fActualProgramData.Description;
                                            if (fActualProgramData.SerialNo != null)
                                            {
                                                Cells[USBPanel.cSerialNo, i + 1] = fActualProgramData.SerialNo;
                                            }
                                            else
                                            {
                                                Cells[USBPanel.cSerialNo, i + 1] = "[none]";
                                            }
                                            Cells[USBPanel.cMaxPower, i + 1] = Rtl.IntToStr(fActualProgramData.MaxPower);
                                            if (fActualProgramData.PnP == 0)
                                            {
                                                Cells[USBPanel.cPnP, i + 1] = "Disabled";
                                            }
                                            else
                                            {
                                                Cells[USBPanel.cPnP, i + 1] = "Enabled";
                                            }
                                            if (fActualProgramData.SelfPowered == 0)
                                            {
                                                Cells[USBPanel.cSelfPowered, i + 1] = "False";
                                            }
                                            else
                                            {
                                                Cells[USBPanel.cSelfPowered, i + 1] = "True";
                                            }
                                            if (fActualProgramData.RemoteWakeup == 0)
                                            {
                                                Cells[USBPanel.cRemoteWakeup, i + 1] = "False";
                                            }
                                            else
                                            {
                                                Cells[USBPanel.cRemoteWakeup, i + 1] = "True";
                                            }
                                            if (fActualProgramData.Rev4)
                                            {
                                                Cells[USBPanel.cRev4, i + 1] = "True";
                                            }
                                            else
                                            {
                                                Cells[USBPanel.cRev4, i + 1] = "False";
                                            }
                                            if (fActualProgramData.IsoIn)
                                            {
                                                Cells[USBPanel.cIsoIn, i + 1] = "True";
                                            }
                                            else
                                            {
                                                Cells[USBPanel.cIsoIn, i + 1] = "False";
                                            }
                                            if (fActualProgramData.IsoOut)
                                            {
                                                Cells[USBPanel.cIsoOut, i + 1] = "True";
                                            }
                                            else
                                            {
                                                Cells[USBPanel.cIsoOut, i + 1] = "False";
                                            }
                                            if (fActualProgramData.PullDownEnable)
                                            {
                                                Cells[USBPanel.cPullDownEnable, i + 1] = "Enabled";
                                            }
                                            else
                                            {
                                                Cells[USBPanel.cPullDownEnable, i + 1] = "Disabled";
                                            }
                                            if (fActualProgramData.SerNumEnable)
                                            {
                                                Cells[USBPanel.cSerNumEnable, i + 1] = "True";
                                            }
                                            else
                                            {
                                                Cells[USBPanel.cSerNumEnable, i + 1] = "Disabled";
                                            }
                                            Cells[USBPanel.cUSBVersion, i + 1] = Rtl.IntToHex(fActualProgramData.USBVersion, 4);
                                        }
                                        break;
                                    default:
                                        {
                                            FT_Error_Check("Reading device " + Rtl.IntToStr(i), iPortStatus);
                                        }
                                        break;
                                }
                            }
                        }
                        if (USBPanel.FT_Close != null)
                        {
                            FT_Error_Check("Closing file " + Rtl.IntToStr(i), USBPanel.FT_Close(iUSBHandle));
                        }
                    }
                }
            }
        }

