        // Delphi: function TUSBGrid.FT_Error_Check(ErrStr: string; PortStatus: Integer): boolean
        public bool FT_Error_Check(string ErrStr, int PortStatus)
        {
            bool Result = false;
            string Str = "";
            bool pHandled = false;
            if (PortStatus == USBPanel.FT_OK)
            {
                Result = true;
            }
            else
            {
                pHandled = false;
                switch (PortStatus)
                {
                    case USBPanel.FT_INVALID_HANDLE:
                        {
                            if (fFTErrorsShown.Contains(tFTError.errInvalidHandle))
                            {
                                pHandled = true;
                            }
                            else
                            {
                                fFTErrorsShown = Rtl.SetUnion(fFTErrorsShown, new HashSet<tFTError> { tFTError.errInvalidHandle });
                                Str = "Error " + ErrStr + " - Invalid Handle...";
                            }
                        }
                        break;
                    case USBPanel.FT_DEVICE_NOT_FOUND:
                        {
                            if (fFTErrorsShown.Contains(tFTError.errDeviceNotFound))
                            {
                                pHandled = true;
                            }
                            else
                            {
                                fFTErrorsShown = Rtl.SetUnion(fFTErrorsShown, new HashSet<tFTError> { tFTError.errDeviceNotFound });
                                Str = "Error " + ErrStr + " - Device Not Found...";
                            }
                        }
                        break;
                    case USBPanel.FT_DEVICE_NOT_OPENED:
                        {
                            if (fFTErrorsShown.Contains(tFTError.errDeviceNotOpenned))
                            {
                                pHandled = true;
                            }
                            else
                            {
                                fFTErrorsShown = Rtl.SetUnion(fFTErrorsShown, new HashSet<tFTError> { tFTError.errDeviceNotOpenned });
                                Str = "Error " + ErrStr + " - Device Not Opened...";
                            }
                        }
                        break;
                    case USBPanel.FT_IO_ERROR:
                        {
                            if (fFTErrorsShown.Contains(tFTError.errIOError))
                            {
                                pHandled = true;
                            }
                            else
                            {
                                fFTErrorsShown = Rtl.SetUnion(fFTErrorsShown, new HashSet<tFTError> { tFTError.errIOError });
                                Str = "Error " + ErrStr + " - General IO Error...";
                            }
                        }
                        break;
                    case USBPanel.FT_INSUFFICIENT_RESOURCES:
                        {
                            if (fFTErrorsShown.Contains(tFTError.errInsufficientResources))
                            {
                                pHandled = true;
                            }
                            else
                            {
                                fFTErrorsShown = Rtl.SetUnion(fFTErrorsShown, new HashSet<tFTError> { tFTError.errInsufficientResources });
                                Str = "Error " + ErrStr + " - Insufficient Resources...";
                            }
                        }
                        break;
                    case USBPanel.FT_INVALID_PARAMETER:
                        {
                            if (fFTErrorsShown.Contains(tFTError.errInvalidParameter))
                            {
                                pHandled = true;
                            }
                            else
                            {
                                fFTErrorsShown = Rtl.SetUnion(fFTErrorsShown, new HashSet<tFTError> { tFTError.errInvalidParameter });
                                Str = "Error " + ErrStr + " - Invalid Parameter ...";
                            }
                        }
                        break;
                    case USBPanel.FT_UNFORMATTED_EEPROM:
                        {
                            if (fFTErrorsShown.Contains(tFTError.errUnformattedEEPROM))
                            {
                                pHandled = true;
                            }
                            else
                            {
                                fFTErrorsShown = Rtl.SetUnion(fFTErrorsShown, new HashSet<tFTError> { tFTError.errUnformattedEEPROM });
                                Str = "Error " + ErrStr + " - Unformatted device...";
                            }
                        }
                        break;
                    default:
                        {
                            if (fFTErrorsShown.Contains(tFTError.errOther))
                            {
                                pHandled = true;
                            }
                            else
                            {
                                fFTErrorsShown = Rtl.SetUnion(fFTErrorsShown, new HashSet<tFTError> { tFTError.errOther });
                                Str = "Error " + ErrStr + " - Undefined Error " + Rtl.IntToStr(PortStatus);
                            }
                        }
                        break;
                }
                Result = false;
                if (fOnErr != null)
                {
                    fOnErr(this, PortStatus, Str, ref pHandled);
                }
                if (!pHandled)
                {
                    if (!Rtl.ComponentState.Contains(Rtl.csDesigning))
                    {
                        if (ErrorStyle == tErrorStyle.esThrowErrors)
                        {
                            throw new Exception(Str);
                        }
                        else if (ErrorStyle == tErrorStyle.esPopUpErrors)
                        {
                            Rtl.MessageDlg(Str, Rtl.mtError, new HashSet<TMsgDlgBtn> { Rtl.mbOK }, 0);
                        }
                    }
                }
            }
            return Result;
        }

    }

